class Node {
  constructor(val = 0, next = null) {
    this.val = val;
    this.next = next;
  }
}

function copyList(head) {
  if (!head) {
    return null;
  }
  const newHead = new Node(head.val);
  let curNew = newHead;
  let curOld = head.next;
  while (curOld) {
    curNew.next = new Node(curOld.val);
    curNew = curNew.next;
    curOld = curOld.next;
  }
  return newHead;
}

function copyListWithDummy(head) {
  const dummy = new Node(0);
  let curNew = dummy;
  let curOld = head;
  while (curOld) {
    curNew.next = new Node(curOld.val);
    curNew = curNew.next;
    curOld = curOld.next;
  }
  return dummy.next;
}

