class Node {
  int val;
  Node next;

  Node(int x) {
    val = x;
    next = null;
  }
}

class CopyList {
  public Node solve(Node head) {
    if (head == null)
      return null;
    Node newHead = new Node(head.val);
    Node curNew = newHead;
    Node curOld = head.next;
    while (curOld != null) {
      curNew.next = new Node(curOld.val);
      curNew = curNew.next;
      curOld = curOld.next;
    }
    return newHead;
  }
}

class CopyListWithDummy {
  public Node solve(Node head) {
    Node dummy = new Node(0); // New list's dummy head
    Node curNew = dummy;
    Node curOld = head;
    while (curOld != null) {
      curNew.next = new Node(curOld.val);
      curNew = curNew.next;
      curOld = curOld.next;
    }
    return dummy.next;
  }
}

